gcLB(){return"\u0627\u0628\u062a\u062f\u0627 \u0644\u06cc\u0646\u06a9 \u0627\u06cc\u062c\u0627\u062f \u06a9\u0646\u06cc\u062f."},
gcMb(){return"\u0627\u0631\u0633\u0627\u0644 \u0628\u0647 \u0634\u0645\u0627\u0631\u0647 \u062f\u06cc\u06af\u0631 (\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc)"},
gcMa(){return"\u062e\u0627\u0644\u06cc = \u0627\u0631\u0633\u0627\u0644 \u0628\u0647 \u0634\u0645\u0627\u0631\u0647 \u062b\u0628\u062a\u200c\u0634\u062f\u0647 \u062f\u0631 \u067e\u0631\u0648\u0646\u062f\u0647 \u0645\u0634\u062a\u0631\u06cc"},
gcPr(){return"\u062b\u0628\u062a \u0633\u0646\u062f \u062f\u0631\u06cc\u0627\u0641\u062a"},
gcPs(){return"\u062f\u0631\u06cc\u0627\u0641\u062a \u0646\u0642\u062f\u06cc\u060c \u0628\u0627\u0646\u06a9\u06cc \u06cc\u0627 \u0686\u06a9 \u0647\u0645\u0631\u0627\u0647 \u0641\u0627\u06a9\u062a\u0648\u0631 \u062b\u0628\u062a \u0634\u0648\u062f. \u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f."},
gbqf(){return"\u0635\u0646\u062f\u0648\u0642"},
gbqg(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u0635\u0646\u062f\u0648\u0642"},
gcPG(){return"\u0628\u0627\u0646\u06a9"},
gcPH(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u062d\u0633\u0627\u0628 \u0628\u0627\u0646\u06a9\u06cc"},
gcPI(){return"\u0686\u06a9"},
gcPJ(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u06cc\u0627 \u062b\u0628\u062a \u0686\u06a9 \u062f\u0631\u06cc\u0627\u0641\u062a\u06cc"},
gcPF(){return"\u0645\u0628\u0644\u063a"},
gcPD(){return"+ \u0635\u0646\u062f\u0648\u0642"},
gcPC(){return"+ \u0628\u0627\u0646\u06a9"},
gcPE(){return"+ \u0686\u06a9"},
gcPK(){return"\u067e\u0631 \u06a9\u0631\u062f\u0646 \u0645\u0627\u0646\u062f\u0647"},
gcPT(){return"\u062d\u0630\u0641 \u0627\u06cc\u0646 \u067e\u0631\u062f\u0627\u062e\u062a"},
gcPO(){return"\u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0634\u062f\u0647"},
gcPS(){return"\u0645\u0627\u0646\u062f\u0647"},
gcPY(){return"\u062a\u0633\u0648\u06cc\u0647 \u06a9\u0627\u0645\u0644"},
gcPP(){return"\u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f"},
gcPM(){return"\u062c\u0645\u0639 \u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0647\u0627 \u0627\u0632 \u0645\u0628\u0644\u063a \u0641\u0627\u06a9\u062a\u0648\u0631 \u0628\u06cc\u0634\u062a\u0631 \u0627\u0633\u062a"},
gcPR(){return"\u0645\u0627\u0646\u062f\u0647 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u0646\u0633\u06cc\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0647\u0645\u06cc\u0646 \u0645\u0634\u062a\u0631\u06cc \u062b\u0628\u062a \u0645\u06cc\u200c\u0634\u0648\u062f."},
gcPQ(){return"\u0645\u0627\u0646\u062f\u0647 \u0631\u0648\u06cc \u062d\u0633\u0627\u0628 \u0645\u0634\u062a\u0631\u06cc \u0646\u0627\u0634\u0646\u0627\u0633 \u062b\u0628\u062a \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0631\u0627\u06cc \u0646\u0633\u06cc\u0647\u060c \u0645\u0634\u062a\u0631\u06cc \u0648\u0627\u0642\u0639\u06cc \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
gcPZ(){return"\u0627\u0631\u0633\u0627\u0644 \u0644\u06cc\u0646\u06a9 \u0628\u0631\u0627\u06cc \u0645\u0627\u0646\u062f\u0647"},
gcQ_(){return"\u0644\u06cc\u0646\u06a9 \u067e\u0631\u062f\u0627\u062e\u062a \u0622\u0646\u0644\u0627\u06cc\u0646 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0645\u0628\u0644\u063a \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0647 \u0627\u0631\u0633\u0627\u0644 \u0634\u0648\u062f"},
gcPW(){return"\u0628\u0631\u0627\u06cc \u067e\u0631\u062f\u0627\u062e\u062a \u0635\u0646\u062f\u0648\u0642\u060c \u0635\u0646\u062f\u0648\u0642 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f"},
gcPV(){return"\u0628\u0631\u0627\u06cc \u067e\u0631\u062f\u0627\u062e\u062a \u0628\u0627\u0646\u06a9\u06cc\u060c \u062d\u0633\u0627\u0628 \u0628\u0627\u0646\u06a9 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f"},
gcPX(){return"\u0628\u0631\u0627\u06cc \u067e\u0631\u062f\u0627\u062e\u062a \u0686\u06a9\u06cc\u060c \u0686\u06a9 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06cc\u0627 \u062b\u0628\u062a \u06a9\u0646\u06cc\u062f"},
gcPN(){return"\u062c\u0645\u0639 \u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0647\u0627 \u0627\u0632 \u0645\u0628\u0644\u063a \u0641\u0627\u06a9\u062a\u0648\u0631 \u0628\u06cc\u0634\u062a\u0631 \u0627\u0633\u062a. \u0645\u0628\u0627\u0644\u063a \u0631\u0627 \u0627\u0635\u0644\u0627\u062d \u06a9\u0646\u06cc\u062f."},
gcPL(){return"\u0647\u0631 \u0631\u062f\u06cc\u0641 \u067e\u0631\u062f\u0627\u062e\u062a \u0628\u0627\u06cc\u062f \u0635\u0646\u062f\u0648\u0642\u060c \u0628\u0627\u0646\u06a9 \u06cc\u0627 \u0686\u06a9 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f"},
gcPU(){return"\u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0686\u0646\u062f \u062f\u0631\u06cc\u0627\u0641\u062a \u0627\u0632 \u06cc\u06a9 \u0646\u0648\u0639 \u062b\u0628\u062a \u06a9\u0646\u06cc\u062f\u061b \u0645\u062b\u0644\u0627\u064b \u062f\u0648 \u06a9\u0627\u0631\u062a/\u0628\u0627\u0646\u06a9. \u0647\u0631 \u0631\u062f\u06cc\u0641 \u06cc\u06a9 \u0633\u0646\u062f \u062f\u0631\u06cc\u0627\u0641\u062a \u062c\u062f\u0627 \u0645\u06cc\u200c\u0633\u0627\u0632\u062f."},
gcPt(){return"\u062c\u0632\u0626\u06cc\u0627\u062a \u0633\u0646\u062f"},
gcPu(){return"\u0628\u0631\u0627\u06cc \u0635\u062f\u0648\u0631 \u062d\u0648\u0627\u0644\u0647\u060c \u0627\u0646\u062a\u062e\u0627\u0628 \u0627\u0646\u0628\u0627\u0631 \u0627\u0644\u0632\u0627\u0645\u06cc \u0627\u0633\u062a"},
gcQc(){return"\u0627\u0634\u062a\u0631\u0627\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc"},
gbqp(){return"\u067e\u0631\u062f\u0627\u062e\u062a \u0622\u0646\u0644\u0627\u06cc\u0646 \u062f\u0631 \u0644\u06cc\u0646\u06a9"},
gbqq(){return"\u0645\u0634\u062a\u0631\u06cc \u0627\u0632 \u0644\u06cc\u0646\u06a9 \u0628\u0647 \u062f\u0631\u06af\u0627\u0647 \u067e\u0631\u062f\u0627\u062e\u062a \u0647\u062f\u0627\u06cc\u062a \u0645\u06cc\u200c\u0634\u0648\u062f"},
gbqk(){return"\u062f\u0631\u06af\u0627\u0647 \u067e\u0631\u062f\u0627\u062e\u062a"},
