gbqd(){return"\u0633\u0628\u062f \u0641\u0639\u0644\u06cc \u0631\u0627 \u0646\u06af\u0647 \u0645\u06cc\u200c\u062f\u0627\u0631\u062f \u0648 \u0641\u0631\u0648\u0634 \u062f\u06cc\u06af\u0631\u06cc \u0634\u0631\u0648\u0639 \u0645\u06cc\u200c\u06a9\u0646\u062f (Ctrl+N)"},
gbqc(){return"\u0633\u0628\u062f \u0641\u0639\u0644\u06cc \u062e\u0627\u0644\u06cc \u0627\u0633\u062a. \u0627\u0628\u062a\u062f\u0627 \u06a9\u0627\u0644\u0627 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f \u06cc\u0627 \u0645\u0634\u062a\u0631\u06cc \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
cPA(a){return"\u062d\u062f\u0627\u06a9\u062b\u0631 "+a+" \u0641\u0631\u0648\u0634 \u0628\u0627\u0632 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u06cc\u062f. \u0627\u0628\u062a\u062f\u0627 \u06cc\u06a9\u06cc \u0631\u0627 \u062b\u0628\u062a \u06cc\u0627 \u062d\u0630\u0641 \u06a9\u0646\u06cc\u062f."},
bqe(a){return"\u0641\u0631\u0648\u0634 "+a},
cPB(a,b){return""+a+" \u0642\u0644\u0645 \xb7 "+b},
gcPz(){return"\u062d\u0630\u0641 \u0627\u06cc\u0646 \u0641\u0631\u0648\u0634"},
gcPy(){return"\u0627\u06cc\u0646 \u0641\u0631\u0648\u0634 \u062d\u0630\u0641 \u0634\u0648\u062f\u061f"},
